#include "AssetRegistry.h"
#include <cctype>
#include <new>
namespace NeoEngine { bool AssetRegistry::ValidId(std::string_view id){if(id.empty()||id.size()>96)return false;for(unsigned char c:id)if(!std::isalnum(c)&&c!='-'&&c!='_'&&c!='.')return false;return true;}uint64_t AssetRegistry::Hash(const std::vector<uint8_t>&b){uint64_t h=1469598103934665603ull;for(auto v:b){h^=v;h*=1099511628211ull;}return h;}const AssetDefinition* AssetRegistry::Find(std::string_view id)const{for(const auto& a:m_Assets)if(a.id==id)return &a;return nullptr;}const std::vector<uint8_t>*AssetRegistry::Data(std::string_view id)const{for(size_t i=0;i<m_Assets.size();++i)if(m_Assets[i].id==id)return &m_Bytes[i];return nullptr;}bool AssetRegistry::Declare(std::string id,AssetKind kind,std::vector<std::string> deps){if(!ValidId(id)){m_LastError=AssetRegistryError::InvalidIdentifier;return false;}if(Find(id)){m_LastError=AssetRegistryError::DuplicateId;return false;}if(m_Assets.size()==kMaxAssets){m_LastError=AssetRegistryError::CapacityReached;return false;}if(deps.size()>kMaxDependencies){m_LastError=AssetRegistryError::MissingDependency;return false;}for(const auto& dep:deps){if(!ValidId(dep)){m_LastError=AssetRegistryError::InvalidIdentifier;return false;}if(!Find(dep)){m_LastError=AssetRegistryError::MissingDependency;return false;}}try{m_Assets.push_back({std::move(id),kind,std::move(deps),AssetState::Declared,0,0});try{m_Bytes.emplace_back();}catch(const std::bad_alloc&){m_Assets.pop_back();throw;}}catch(const std::bad_alloc&){m_LastError=AssetRegistryError::CapacityReached;return false;}m_LastError=AssetRegistryError::None;return true;}bool AssetRegistry::ImportBytes(std::string id,AssetKind kind,std::vector<std::string>deps,std::vector<uint8_t>b){const size_t importedBytes=b.size();if(importedBytes>kMaxAssetBytes||m_StoredBytes+importedBytes>kMaxStoredBytes){m_LastError=AssetRegistryError::ByteLimitExceeded;return false;}auto h=Hash(b);if(!Declare(std::move(id),kind,std::move(deps)))return false;m_Assets.back().contentHash=h;m_Assets.back().byteSize=static_cast<uint32_t>(importedBytes);m_StoredBytes+=importedBytes;m_Bytes.back()=std::move(b);return true;}bool AssetRegistry::ReplaceBytes(std::string_view id,std::vector<uint8_t>b){if(!ValidId(id)){m_LastError=AssetRegistryError::InvalidIdentifier;return false;}for(size_t i=0;i<m_Assets.size();++i)if(m_Assets[i].id==id){if(m_Assets[i].state!=AssetState::Ready){m_LastError=AssetRegistryError::InvalidState;return false;}const size_t oldSize=m_Bytes[i].size();if(b.size()>kMaxAssetBytes||m_StoredBytes-oldSize+b.size()>kMaxStoredBytes){m_LastError=AssetRegistryError::ByteLimitExceeded;return false;}const uint64_t hash=Hash(b);const uint32_t size=static_cast<uint32_t>(b.size());m_Bytes[i]=std::move(b);m_Assets[i].contentHash=hash;m_Assets[i].byteSize=size;m_StoredBytes=m_StoredBytes-oldSize+size;m_LastError=AssetRegistryError::None;return true;}m_LastError=AssetRegistryError::MissingAsset;return false;}bool AssetRegistry::MarkReady(std::string_view id){if(!ValidId(id)){m_LastError=AssetRegistryError::InvalidIdentifier;return false;}for(auto& a:m_Assets)if(a.id==id){if(a.state!=AssetState::Declared){m_LastError=AssetRegistryError::InvalidState;return false;}for(const auto& dep:a.dependencies){const auto* found=Find(dep);if(!found||found->state!=AssetState::Ready){m_LastError=AssetRegistryError::MissingDependency;return false;}}a.state=AssetState::Ready;m_LastError=AssetRegistryError::None;return true;}m_LastError=AssetRegistryError::MissingAsset;return false;} }
